// "\u{0}" [ctx = 64] / [ctx = 0]
func (p *parser) e6() (*Node, bool) {
	m0 := p.mark()
	ch, _, more := p.peek()
	if !(more && (ch == 0)) && p.depth+0 <= maxDepth {
		p.expect(p.pos, 5)
	} else {
		prevCut := p.cut
		p.cut = false
		v, ok := p.e4()
		cut := p.cut
		p.cut = prevCut
		if ok {
			return v, true
		}
		p.reset(m0)
		if cut {
			return nil, false
		}
	}
	{
		prevCut := p.cut
		p.cut = false
		v, ok := p.e5()
		cut := p.cut
		p.cut = prevCut
		if ok {
			return v, true
		}
		p.reset(m0)
		if cut {
			return nil, false
		}
	}
	return nil, false
}

